00047 std::shared_ptr<ConfigFile> CORE::ConfigLoader::LoadCOnfigFile(const char* path)
00048 {
00049     TrPr(ctx, __func__)
00050         std::ifstream file(path);
00051     
00052     if (!file.is_open()) {
00053         throw std::runtime_error("Could not open config file.");
00054     }
00055     nlohmann::json j;
00056     file >> j;
00057    auto Name = j["name"].get<std::string>();
00058     auto Modelpath = j["modelPath"].get<std::string>();
00059     ConfigFile::ConfigType ConnfigType = ConfigFile::toConfigType(j["configType"].get<std::string>());
00060    std::vector<std::string> Texturepaths;
00061     for (const auto& path : j["texturePaths"]) {
00062          Texturepaths.push_back(path.get<std::string>());
00063     }
00064     nlohmann::json Data=j["data"];
00065 
00066     //for (const auto& path : j["data"]) {
00067     //    //Texturepaths.push_back(path.get<std::string>());
00068     //   // std::string dataString = ;
00069     //    Data.push_back(path.get<std::string>());
00070 
00071     //}
00072     if (ConnfigType == ConfigFile::ConfigType::Building) { std::shared_ptr<ConfigFile> ret = std::make_shared<Buidling>(Buidling(Name, Modelpath, Texturepaths, ConnfigType, Data));CORE::ConfigLoader::ConfigDatabase[ConfigFile::ConfigType::Building][Name]=ret; TrPrE(ctx) return ret; }
00073     if (ConnfigType == ConfigFile::ConfigType::Vehicle) { std::shared_ptr<ConfigFile> ret = std::make_shared<Vehicle>(Vehicle(Name, Modelpath, Texturepaths, ConnfigType, Data)); CORE::ConfigLoader::ConfigDatabase[ConfigFile::ConfigType::Vehicle][Name] = ret; TrPrE(ctx) return ret;}
00074     if (ConnfigType == ConfigFile::ConfigType::Projectile) { std::shared_ptr<ConfigFile> ret = std::make_shared<Projectile>(Projectile(Name, Modelpath, Texturepaths, ConnfigType, Data)); CORE::ConfigLoader::ConfigDatabase[ConfigFile::ConfigType::Projectile][Name] = ret; TrPrE(ctx) return ret;}
00075     if (ConnfigType == ConfigFile::ConfigType::Particle) { std::shared_ptr<ConfigFile> ret = std::make_shared<Particle>(Particle(Name, Modelpath, Texturepaths, ConnfigType, Data)); CORE::ConfigLoader::ConfigDatabase[ConfigFile::ConfigType::Particle][Name] = ret; TrPrE(ctx) return ret;}
00076     if (ConnfigType == ConfigFile::ConfigType::Island) { std::shared_ptr<ConfigFile> ret = std::make_shared<Island>(Island(Name, Modelpath, Texturepaths, ConnfigType, Data)); CORE::ConfigLoader::ConfigDatabase[ConfigFile::ConfigType::Island][Name] = ret; TrPrE(ctx) return ret;}
00077     if (ConnfigType == ConfigFile::ConfigType::AiObject) { std::shared_ptr<ConfigFile> ret = std::make_shared<AiObject>(AiObject(Name, Modelpath, Texturepaths, ConnfigType, Data)); CORE::ConfigLoader::ConfigDatabase[ConfigFile::ConfigType::AiObject][Name] = ret; TrPrE(ctx) return ret;}
