00079     if (ConnfigType == ConfigFile::ConfigType::Manager) { std::shared_ptr<ConfigFile> ret = std::make_shared<Manager>(Manager(Name, Modelpath, Texturepaths, ConnfigType, Data)); CORE::ConfigLoader::ConfigDatabase[ConfigFile::ConfigType::Manager][Name] = ret; TrPrE(ctx) return ret;}
00080     if (ConnfigType == ConfigFile::ConfigType::VertexShader) { std::shared_ptr<ConfigFile> ret = std::make_shared<VertexShader>(VertexShader(Name, Modelpath, Texturepaths, ConnfigType, Data)); CORE::ConfigLoader::ConfigDatabase[ConfigFile::ConfigType::VertexShader][Name] = ret; TrPrE(ctx) return ret;}
00081     if (ConnfigType == ConfigFile::ConfigType::FragmentShader) { std::shared_ptr<ConfigFile> ret = std::make_shared<FragmentShader>(FragmentShader(Name, Modelpath, Texturepaths, ConnfigType, Data)); CORE::ConfigLoader::ConfigDatabase[ConfigFile::ConfigType::FragmentShader][Name] = ret; TrPrE(ctx) return ret;}
