00128 {
00129     TrPr(ctx, __func__)
00130         int i = 0;
00131     for (const auto material : CORE::ConfigLoader::ConfigDatabase[ConfigFile::ConfigType::Material]) {
00132         auto a = std::dynamic_pointer_cast<Material>(material.second).get();
00133         if (a->ShaderCount == 2) {
00134             auto oo= CORE::ConfigLoader::ConfigDatabase[ConfigFile::ConfigType::VertexShader][a->VertexShader];
00135             auto aa= CORE::ConfigLoader::ConfigDatabase[ConfigFile::ConfigType::VertexShader][a->FragmentShader];
00136             PAIN::Render::mats.push_back(ShaderFromCFGFile(CORE::ConfigLoader::ConfigDatabase[ConfigFile::ConfigType::VertexShader][a->VertexShader], CORE::ConfigLoader::ConfigDatabase[ConfigFile::ConfigType::FragmentShader][a->FragmentShader]));
00137 
00138         }
00139         else if (a->ShaderCount == 3) {
00140             PAIN::Render::mats.push_back(ShaderFromCFGFile(CORE::ConfigLoader::ConfigDatabase[ConfigFile::ConfigType::VertexShader][a->VertexShader], CORE::ConfigLoader::ConfigDatabase[ConfigFile::ConfigType::FragmentShader][a->FragmentShader], CORE::ConfigLoader::ConfigDatabase[ConfigFile::ConfigType::GeometryShader][a->GeometryShader]));
00141 
00142 
00143         }
00144             i++;
